import{_ as e,o as i,c as o,a2 as a}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"Symbiotic Labor Law","description":"","frontmatter":{},"headers":[],"relativePath":"en/41-共生劳动法.md","filePath":"en/41-共生劳动法.md","lastUpdated":1789183869000}'),r={name:"en/41-共生劳动法.md"};function n(s,t,l,c,h,d){return i(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="symbiotic-labor-law" tabindex="-1">Symbiotic Labor Law <a class="header-anchor" href="#symbiotic-labor-law" aria-label="Permalink to &quot;Symbiotic Labor Law&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Content</th></tr></thead><tbody><tr><td>Document No.</td><td>41</td></tr><tr><td>Module</td><td>Legal System and Governance Framework</td></tr><tr><td>Core Keywords</td><td>Symbiotic labor, More work more reward, Labor rights, Joint-output contracting, Anti-exploitation</td></tr></tbody></table><h2 id="i-legislative-purpose-and-basic-principles" tabindex="-1">I. Legislative Purpose and Basic Principles <a class="header-anchor" href="#i-legislative-purpose-and-basic-principles" aria-label="Permalink to &quot;I. Legislative Purpose and Basic Principles&quot;">​</a></h2><p>The <em>Symbiotic Labor Law</em> is one of the core laws of the Anchor Symbiotic Civilization&#39;s legal system, standing alongside the <em>Symbiotic Constitution</em>. It aims to regulate all labor and contribution activities within the Hengyuan Universe, establish the distribution order of &quot;more work, more reward; self-growth and self-development,&quot; and eradicate, at the legal level, the soil for predatory exploitation.</p><p>This Law establishes the following basic principles:</p><table tabindex="0"><thead><tr><th>Principle</th><th>Connotation</th></tr></thead><tbody><tr><td>Labor Dignity</td><td>All lawful labor is protected by law; the personal dignity of laborers shall not be violated</td></tr><tr><td>More Work, More Reward</td><td>Labor remuneration is directly linked to the amount of contribution; the greater the contribution, the higher the income; gain without labor is prohibited</td></tr><tr><td>Voluntary Labor</td><td>Forced labor and slavery are prohibited; laborers have the right to freely choose the content and manner of labor</td></tr><tr><td>Fair Remuneration</td><td>Equal pay for equal work; remuneration discrimination based on race, cultivation, or birth is prohibited</td></tr><tr><td>Labor Protection</td><td>The state and civilization have the obligation to provide laborers with a safe working environment and basic social security</td></tr><tr><td>Symbiotic Collaboration</td><td>Collaboration and mutual assistance among laborers are encouraged; vicious competition and zero-sum games are opposed</td></tr></tbody></table><h2 id="ii-basic-rights-of-laborers" tabindex="-1">II. Basic Rights of Laborers <a class="header-anchor" href="#ii-basic-rights-of-laborers" aria-label="Permalink to &quot;II. Basic Rights of Laborers&quot;">​</a></h2><p>The Symbiotic Labor Law confers the following rights upon all life forms with labor capacity within the Hengyuan Universe:</p><ol><li><strong>Right to Equal Employment</strong>: No life shall be discriminated against in job seeking and employment on the basis of race, cultivation, birth, gender, or other factors.</li><li><strong>Right to Free Choice of Occupation</strong>: Laborers have the right to choose their profession, position, and place of work according to their own will and ability, and the right to change occupations in accordance with the law.</li><li><strong>Right to Reasonable Remuneration</strong>: Laborers have the right to receive remuneration matching their labor contribution; remuneration shall not be lower than the minimum guarantee standard stipulated by the civilization.</li><li><strong>Right to Rest and Leave</strong>: Laborers have the right to reasonable working time arrangements and regular leave; unlimited extension of working hours is prohibited.</li><li><strong>Right to Labor Safety</strong>: Laborers have the right to work in a safe and hygienic environment; employers must provide labor protection conditions that meet standards.</li><li><strong>Right to Vocational Training</strong>: Laborers have the right to receive vocational skills training and cultivation guidance; employers and the state have the obligation to provide training resources.</li><li><strong>Right to Association and Consultation</strong>: Laborers have the right to organize or join laborers&#39; associations in accordance with the law, and the right to protect their own interests through collective consultation.</li><li><strong>Right to Appeal and Remedy</strong>: When labor rights and interests are infringed, laborers have the right to file appeals and lawsuits with labor arbitration institutions and the Symbiotic Court.</li></ol><h2 id="iii-legalization-of-the-joint-output-contracting-mechanism" tabindex="-1">III. Legalization of the Joint-Output Contracting Mechanism <a class="header-anchor" href="#iii-legalization-of-the-joint-output-contracting-mechanism" aria-label="Permalink to &quot;III. Legalization of the Joint-Output Contracting Mechanism&quot;">​</a></h2><p>The Joint-Output Contracting Mechanism is the core institution of resource distribution in the Anchor Symbiotic Civilization; the <em>Symbiotic Labor Law</em> fixes it in legal form:</p><ul><li><strong>Contracting Subjects</strong>: Any life with labor capacity may serve as a contracting subject; individuals or collectives may both contract.</li><li><strong>Contracting Content</strong>: Including but not limited to cultivation resource development, plane maintenance, knowledge inheritance, technological research, public services, and other fields.</li><li><strong>Contracting Term</strong>: Determined according to the nature of the contracting content; short-term contracts last one to three years, long-term contracts five to twenty years, and renewal is possible upon expiration.</li><li><strong>Income Distribution</strong>: The contractor&#39;s income is directly linked to output; part of the output is turned over to the public accumulation, and the remainder belongs to the contractor.</li><li><strong>Exit Mechanism</strong>: Contractors have the right to exit the contract after giving advance notice within a reasonable period; they shall not be forcibly bound to the contractual relationship.</li><li><strong>Dispute Resolution</strong>: Contract disputes are resolved preferentially through labor arbitration; those dissatisfied with the arbitration result may sue in the Symbiotic Court.</li></ul><h2 id="iv-special-labor-protection" tabindex="-1">IV. Special Labor Protection <a class="header-anchor" href="#iv-special-labor-protection" aria-label="Permalink to &quot;IV. Special Labor Protection&quot;">​</a></h2><p>In response to the special needs of different life forms within the Hengyuan Universe, this Law establishes special labor protection institutions:</p><table tabindex="0"><thead><tr><th>Protected Group</th><th>Special Protection Measures</th></tr></thead><tbody><tr><td>Junior cultivators</td><td>High-risk labor beyond their capacity shall not be arranged; mentor guidance must be provided</td></tr><tr><td>Female lives during pregnancy and childbirth</td><td>Entitled to paid maternity leave of no less than six months; high-intensity labor shall not be arranged during the nursing period</td></tr><tr><td>Disabled and injured lives</td><td>Entitled to reasonable work position adjustment and barrier-free labor environment guarantees</td></tr><tr><td>Non-human laborers</td><td>Employers must respect the physiological characteristics and cultural customs of non-human races and provide adapted labor conditions</td></tr><tr><td>Elderly laborers</td><td>May apply to reduce labor intensity or transfer to advisory positions upon reaching a certain age</td></tr></tbody></table><h2 id="v-legal-liability-and-implementation-guarantees" tabindex="-1">V. Legal Liability and Implementation Guarantees <a class="header-anchor" href="#v-legal-liability-and-implementation-guarantees" aria-label="Permalink to &quot;V. Legal Liability and Implementation Guarantees&quot;">​</a></h2><p>Employers who violate the provisions of this Law shall bear the following liabilities depending on the severity of the circumstances:</p><ol><li>Pay the laborer&#39;s due remuneration and compensation (compensation of one to three times the arrears).</li><li>Be ordered to rectify within a time limit; failure to rectify within the time limit results in fines.</li><li>For serious circumstances, the business license shall be revoked and the responsible persons prohibited from engaging in management work for a certain period.</li><li>For crimes, criminal liability shall be pursued in accordance with the law.</li></ol><p>The state establishes labor inspection institutions responsible for supervising and inspecting employers&#39; compliance with the labor law. Laborers&#39; associations have the right to represent laborers in labor inspection and collective consultation.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>The <em>Symbiotic Labor Law</em> is the legal carrier of the &quot;more work, more reward&quot; philosophy of the Anchor Symbiotic Civilization. It transforms labor from an object of exploitation into a respected right, and distribution from predatory appropriation into contribution-based returns, laying a solid labor institution foundation for the joint advancement of all races.</p><h2 id="related-documents" tabindex="-1">Related Documents <a class="header-anchor" href="#related-documents" aria-label="Permalink to &quot;Related Documents&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Symbiotic Constitution: General Principles)</li><li>06-多劳多得分配原理 (Principles of More Work, More Reward Distribution)</li><li>22-资源分配联产承包机制 (Resource Distribution Joint-Output Contracting Mechanism)</li><li>42-消费者保护法 (Consumer Protection Law)</li></ul>',23)])])}const m=e(r,[["render",n]]);export{u as __pageData,m as default};
